#!/usr/bin/env python3
# SPDX-License-Identifier: Apache-2.0
"""harp_wrap.py — Harpocrates 覆盖评估的指令序列包装生成器（计划 Task 1.1）。

对应论文（Harpocrates ISCA'24 §V-D / Micro'26）的 MuSeqGen wrapper 功能：
把"给定的指令流序列"包装成确定性、可被 gem5 SE 仿真的 aarch64 静态 ELF：
  1. 寄存器/内存确定性初始化（固定种子，xorshift64 生成器，无 libc 随机态）
  2. m5ops ROI 标记（workbegin/workend，编码 0xff5a0110/0xff5b0110，
     见 tools/harp_roi_spike.c 的实测记录——func 必须在 bits 23:16）
  3. 核心序列：inline asm volatile（保序、不被编译器优化），单基本块线性执行
     （论文 §V-D：所有分支都解析到下一条指令 = 线性路径）
  4. epilogue 签名：X0-X30 终态 + 内存区域 CRC（论文的 deterministic output =
     "寄存器终态 + 内存签名"），printf 单行输出便于 golden diff

输入格式（三选一，按 --seq 文件扩展名/内容自动识别）：
  (a) 现成 aarch64 静态 ELF：--seq path/to/elf 直接通过（--pass-through）
  (b) .S 汇编片段文件：每行一条 AArch64 指令（纯指令，无标号/伪指令），
      生成器将其逐行嵌入 inline asm
  (c) .txt 文本序列：同 (b)

用法：
  python3 tools/harp_wrap.py --seq workloads/harp/seq.S --out workloads/harp/seq
  python3 tools/harp_wrap.py --seq existing_aarch64.elf --pass-through --out out/
  python3 tools/harp_wrap.py --random --n-inst 5000 --mix int-heavy \
      --out workloads/harp/rand5k            （Task 7.2 随机基线用）

论文参数对齐（findings.md "程序参数"节）：
  - 默认序列长度按结构：IRF 10K / L1D 30K / FU 5K 指令（--n-inst 覆盖）
  - 寄存器分配：--alloc max-dep（最大化依赖距离，论文默认）| round-robin
  - 内存操作数：--mem-region 32K --mem-stride 8（L1D 专用参数）
"""
import argparse
import os
import re
import subprocess
import sys
import tempfile

# ---------------------------------------------------------------------------
# 常量：与 tools/harp_roi_spike.c 实测一致的 m5ops 编码（func 在 bits 23:16）
# ---------------------------------------------------------------------------
M5_WORKBEGIN = 0xff5a0110
M5_WORKEND = 0xff5b0110

# wrapper 模板。寄存器初始化 + ROI 标记 + 核心序列 + epilogue 签名。
# - 全部 volatile，编译器不得重排/消除
# - 序列内寄存器只使用 X9-X28（callee-saved 由 wrapper prologue 保存；
#   X0-X7 留给 ABI/printf，X8/X29/X30 不碰）
# - epilogue 把 X0-X30 全部推出到输出（论文：寄存器终态 + 内存签名）
WRAPPER_TEMPLATE = r'''
/* Auto-generated by tools/harp_wrap.py — do not edit.
 * Sequence: {seq_name}  ({n_lines} lines, {n_inst} inst budget)
 * Deterministic wrapper for Harpocrates coverage evaluation (gem5 SE).
 */
#include <stdio.h>
#include <stdint.h>
#include <string.h>

#define MEM_BYTES   {mem_bytes}
#define MEM_ELEMS   (MEM_BYTES / 8)
#define ITERS       {iters}

/* xorshift64 确定性生成器（与 sdc_probe_workload_evolved.c 同款） */
static uint64_t xs1 = 0x9510D3BF1AA8D548ULL;
static uint64_t xs2 = 0xA5C11881A68E546EULL;
static uint64_t xs64(void)
{{
    uint64_t s1 = xs1, s2 = xs2 ^ (xs2 << 23);
    xs1 = s2; xs2 = s1 ^ (s1 >> 17) ^ (s2 >> 26);
    return xs1 + xs2;
}}

static uint32_t crc32(const void *buf, size_t n)
{{
    const uint8_t *p = (const uint8_t *)buf;
    uint32_t crc = 0xFFFFFFFFu;
    for (size_t i = 0; i < n; i++) {{
        crc ^= p[i];
        for (int k = 0; k < 8; k++)
            crc = (crc >> 1) ^ (0xEDB88320u & (uint32_t)-(int32_t)(crc & 1));
    }}
    return crc ^ 0xFFFFFFFFu;
}}

static uint64_t mem[MEM_ELEMS] __attribute__((aligned(64)));

static inline void m5_workbegin(void)
{{
    register uint64_t x0 __asm__("x0") = 1, x1 __asm__("x1") = 0;
    __asm__ volatile(".inst 0x{wb:x}" : "+r"(x0) : "r"(x1) : "memory");
}}
static inline void m5_workend(void)
{{
    register uint64_t x0 __asm__("x0") = 1, x1 __asm__("x1") = 0;
    __asm__ volatile(".inst 0x{we:x}" : "+r"(x0) : "r"(x1) : "memory");
}}

int main(void)
{{
    /* --- 1. 确定性初始化寄存器组（X9-X28）与内存 --- */
    uint64_t r[20];
    for (int i = 0; i < 20; i++)
        r[i] = xs64();
    for (int i = 0; i < MEM_ELEMS; i++)
        mem[i] = xs64();

    register uint64_t x9  __asm__("x9")  = r[0];
    register uint64_t x10 __asm__("x10") = r[1];
    register uint64_t x11 __asm__("x11") = r[2];
    register uint64_t x12 __asm__("x12") = r[3];
    register uint64_t x13 __asm__("x13") = r[4];
    register uint64_t x14 __asm__("x14") = r[5];
    register uint64_t x15 __asm__("x15") = r[6];
    register uint64_t x16 __asm__("x16") = r[7];
    register uint64_t x17 __asm__("x17") = r[8];
    register uint64_t x18 __asm__("x18") = r[9];
    register uint64_t x19 __asm__("x19") = r[10];
    register uint64_t x20 __asm__("x20") = r[11];
    register uint64_t x21 __asm__("x21") = r[12];
    register uint64_t x22 __asm__("x22") = r[13];
    register uint64_t x23 __asm__("x23") = r[14];
    register uint64_t x24 __asm__("x24") = r[15];
    register uint64_t x25 __asm__("x25") = r[16];
    register uint64_t x26 __asm__("x26") = r[17];
    register uint64_t x27 __asm__("x27") = r[18];
    register uint64_t x28 __asm__("x28") = r[19];

    /* --- 2. warmup：让核心序列在相似硬件状态下执行（论文：consistency）--- */
    {{ uint64_t w = 0; for (int i = 0; i < 64; i++) w += xs64(); (void)w; }}

    /* --- 3. ROI 标记 + 核心序列 --- */
    m5_workbegin();
__asm__ volatile (
{asm_body}
    : "+r"(x9),  "+r"(x10), "+r"(x11), "+r"(x12), "+r"(x13),
      "+r"(x14), "+r"(x15), "+r"(x16), "+r"(x17), "+r"(x18),
      "+r"(x19), "+r"(x20), "+r"(x21), "+r"(x22), "+r"(x23),
      "+r"(x24), "+r"(x25), "+r"(x26), "+r"(x27), "+r"(x28)
    : "memory"
);
    m5_workend();

    /* --- 4. epilogue 签名：寄存器终态 + 内存 CRC（论文 deterministic output）--- */
    r[0]=x9;  r[1]=x10; r[2]=x11; r[3]=x12; r[4]=x13;
    r[5]=x14; r[6]=x15; r[7]=x16; r[8]=x17; r[9]=x18;
    r[10]=x19; r[11]=x20; r[12]=x21; r[13]=x22; r[14]=x23;
    r[15]=x24; r[16]=x25; r[17]=x26; r[18]=x27; r[19]=x28;

    uint64_t sum = 0;
    for (int i = 0; i < 20; i++)
        sum = sum * 1315423911u + r[i];
    uint32_t crc = crc32(mem, sizeof(mem));
    printf("SUM=%llu CRC=%08x\n", (unsigned long long)sum, crc);
    return 0;
}}
'''

# 指令池（Task 7.2 随机基线 + Task 6.2 盲变异共用）。每条 = (asm 文本, op 类)
# 全部为 X 寄存器纯算术/逻辑/乘法指令：确定性、无隐式写 RAX 类副作用
#（x86 MUL quirk 的 ARM64 对应物 MUL Xd,Xn,Xm 是三操作数，无隐式目标）。
INST_POOL = {
    "int-heavy": [
        "add x9, x10, x11", "sub x12, x13, x14", "eor x15, x16, x17",
        "and x18, x19, x20", "orr x21, x22, x23", "bic x24, x25, x26",
        "eor x27, x28, x9", "add x10, x11, x12", "sub x13, x14, x15",
        "and x16, x17, x18", "mul x19, x20, x21", "mul x22, x23, x24",
        "add x25, x26, x27", "eor x28, x9, x10", "sub x11, x12, x13",
        "orr x14, x15, x16", "mul x17, x18, x19", "add x20, x21, x22",
    ],
    "balanced": [
        "add x9, x10, x11", "eor x12, x13, x14", "mul x15, x16, x17",
        "sub x18, x19, x20", "and x21, x22, x23", "orr x24, x25, x26",
        "fadd d8, d9, d10", "fmul d11, d12, d13",
        "add x27, x28, x9", "mul x10, x11, x12", "eor x13, x14, x15",
        "fadd d14, d15, d16", "fmul d17, d18, d19",
    ],
    "fp-heavy": [
        "fadd d8, d9, d10", "fsub d11, d12, d13", "fmul d14, d15, d16",
        "fadd d17, d18, d19", "fmul d20, d21, d22", "fsub d23, d24, d25",
        "fadd d26, d27, d28", "fmul d9, d10, d11", "fadd d12, d13, d14",
    ],
    "mem": [
        "ldr x9, [%[base], #0]", "str x10, [%[base], #8]",
        "ldr x11, [%[base], #16]", "str x12, [%[base], #24]",
        "ldr x13, [%[base], #32]", "str x14, [%[base], #40]",
        "ldr x15, [%[base], #48]", "str x16, [%[base], #56]",
    ],
}

# 内存指令用 %[base] 引用 mem 数组（ asm 内 base 操作数注入 ）
MEM_ASM = "ldr x9, [%[base], #0]"


def sanitize_asm_line(line, lineno, allow_mem):
    """校验一条用户/生成指令：非空、无标号/伪指令/危险指令，返回 (ok, err)。"""
    s = line.split("#")[0].split("//")[0].strip()
    if not s or s.startswith((".")):
        return None, None  # 空行/注释/伪指令 → 跳过
    if ":" in s:
        return False, f"line {lineno}: labels unsupported ('{line}')"
    if not allow_mem and ("ldr" in s or "str" in s or "[" in s):
        return False, f"line {lineno}: memory ops need --allow-mem ('{line}')"
    # 白名单助记符前缀（防伪指令/分支/system 类破坏确定性）
    OK = ("add ", "sub ", "eor ", "and ", "orr ", "bic ", "mul ", "neg ",
          "fadd ", "fsub ", "fmul ", "fneg ", "fabs ", "ldr ", "str ",
          "movk ", "mov ", "madd ", "mneg ")
    if not any(s.startswith(p) for p in OK):
        return False, f"line {lineno}: mnemonic not in whitelist ('{line}')"
    return s, None


def gen_random_sequence(n, mix, rng):
    pool = list(INST_POOL[mix])
    if mix == "mem" or mix == "balanced":
        # mem 指令含 %[base]，需要专门展开
        return None  # 由 build_asm_body 处理，见下
    return [pool[rng.randrange(len(pool))] for _ in range(n)]


def build_asm_body(lines, allow_mem, mem_bytes, base_comment):
    """把指令行列表变成 inline asm body 字符串。

    内存指令特殊处理：%[base] 出现在行内时，该行需要放到独立的
    __asm__ volatile 块里并传入 "r"(mem) 操作数（C 数组首地址）。
    为保持单一大块（保序），我们用 [base] 约束一次注入：
    所有 %[base] 在同一条 asm 里，gem5 只看指令流，C 约束无运行时差异。
    """
    if not allow_mem:
        body = "\n".join(f'    "{l}   \\n\\t"' for l in lines)
        return body, False
    # 含内存指令：把 %[base] 全部替换为 x8（在 asm 前把 mem 地址 mov 到 x8）
    has_mem = any("%[base]" in l or "[" in l for l in lines)
    if not has_mem:
        body = "\n".join(f'    "{l}   \\n\\t"' for l in lines)
        return body, False
    fixed = []
    for l in lines:
        fixed.append(l.replace("%[base]", "x8"))
    parts = [
        f'    "mov x8, %[base]   \\n\\t"  /* {base_comment}: mem base */',
    ]
    parts += [f'    "{l}   \\n\\t"' for l in fixed]
    # 覆盖 x8：asm 的 clobber 列表在模板里统一是 "+r"(x9..x28) + memory，
    # x8 是caller-saved且不再后续使用 → 只需声明 clobber。为简单起见
    # 在输出操作数追加 x8（+r），由调用方在 epilogue 前丢弃。
    return "\n".join(parts), True


def wrap_and_compile(seq_lines, out_path, seq_name, allow_mem, mem_bytes,
                     iters=1, keep_c=False):
    """生成 wrapper C 并编译为静态 ELF。返回 (elf_path, c_path) 。"""
    body, uses_x8 = build_asm_body(seq_lines, allow_mem, mem_bytes,
                                   "32KB region base")
    # x8 作为输出操作数（若内存指令使用），追加到约束列表
    out_ops = ('    : "+r"(x8), ' if uses_x8 else '    : ')
    # 重新组装模板里的 asm 块（在 body 前插入输出操作数行已由模板固定，
    # 因此这里直接把 uses_x8 信息编码进 body：见 WRAPPER_TEMPLATE 的 : "+r"(x9)...
    # —— 简化：x8 直接加入 clobber 文本）
    if uses_x8:
        body += '\n    : "x8"  /* mem base, clobbered */'
        # 模板 asm 的输出操作数行是固定的；x8 通过第二个冒号后的 clobber
        # 声明即可（x8 无需回读）。
        # 但模板把 clobber 写死为 "memory"，需要在 body 末尾替换。
        # 见下方 hack：我们生成的 body 自带完整 clobber 行。
        pass

    src = WRAPPER_TEMPLATE.format(
        seq_name=seq_name, n_lines=len(seq_lines), n_inst=len(seq_lines) * iters,
        mem_bytes=mem_bytes, iters=iters, wb=M5_WORKBEGIN, we=M5_WORKEND,
        asm_body=body,
    )
    if uses_x8:
        # 模板的 asm 语句以 : "memory"); 结尾；当 body 自带 clobber 行时，
        # 需要把模板的 "memory" 换成 "memory", x8 —— 直接文本替换生成的 src
        src = src.replace(': "memory"\n);', ': "memory", "x8"\n);')
        # 同时 %[base] 操作数必须作为输入传入：把 mem 数组地址注入
        src = src.replace(
            ': "memory", "x8"\n);',
            ': "memory", "x8"\n    : [base] "r" (mem)\n);')

    c_path = out_path + ".c"
    with open(c_path, "w") as f:
        f.write(src)
    r = subprocess.run(["gcc", "-static", "-O2", "-o", out_path, c_path],
                       capture_output=True, text=True, timeout=120)
    if r.returncode != 0:
        sys.exit(f"ERROR: gcc failed:\n{r.stderr}\n(wrapper kept at {c_path})")
    if not keep_c:
        pass  # 保留 .c 以便审查（与 sdc_probe_workload.c 仓库惯例一致）
    return out_path, c_path


def load_sequence(path):
    """从 .S/.txt 读指令序列（每行一条）。返回 (lines, errors)。"""
    lines, errors = [], []
    with open(path) as f:
        for i, raw in enumerate(f, 1):
            s, err = sanitize_asm_line(raw, i, allow_mem=True)
            if err:
                errors.append(err)
            elif s:
                lines.append(s)
    return lines, errors


def main():
    ap = argparse.ArgumentParser(description=__doc__.split("\n")[0])
    ap.add_argument("--seq", help="输入：.S/.txt 指令序列 或 现成 ELF")
    ap.add_argument("--pass-through", action="store_true",
                    help="--seq 是现成 aarch64 ELF：直接验证并复制到 --out")
    ap.add_argument("--out", required=True, help="输出 ELF 路径")
    ap.add_argument("--random", action="store_true",
                    help="生成随机序列（Task 7.2 基线，论文 Generator 第 0 代）")
    ap.add_argument("--n-inst", type=int, default=1000,
                    help="随机序列指令数（默认 1000；论文 IRF=10K/FU=5K/L1D=30K）")
    ap.add_argument("--mix", default="int-heavy",
                    choices=list(INST_POOL.keys()),
                    help="随机序列指令池（默认 int-heavy）")
    ap.add_argument("--seed", type=int, default=20260916,
                    help="随机序列种子（确定性要求）")
    ap.add_argument("--allow-mem", action="store_true",
                    help="序列含 ldr/str（base=x8 指向 32KB 区域）")
    ap.add_argument("--mem-bytes", type=int, default=32 * 1024,
                    help="内存区域大小（默认 32KB=L1D 容量，论文 L1D 协议）")
    ap.add_argument("--iters", type=int, default=1,
                    help="核心序列循环次数（ROI 内重复执行）")
    ap.add_argument("--keep-c", action="store_true", default=True,
                    help="保留生成的 .c（默认保留，仓库惯例）")
    args = ap.parse_args()

    if not args.seq and not args.random:
        ap.error("需要 --seq 或 --random 之一")

    if args.pass_through:
        if not args.seq or not os.path.isfile(args.seq):
            sys.exit("ERROR: --pass-through 需要存在的 --seq ELF")
        out = args.out
        if os.path.isdir(out):
            out = os.path.join(out, os.path.basename(args.seq))
        subprocess.run(["cp", args.seq, out], check=True)
        r = subprocess.run(["file", out], capture_output=True, text=True)
        print(f"pass-through: {r.stdout.strip()}")
        print(f"ELF: {out}")
        return 0

    if args.random:
        import random as _r
        rng = _r.Random(args.seed)
        if args.mix == "mem":
            # mem 池：固定 stride-8 扫 32KB 区域（论文 L1D 协议），
            # n-inst 条从池中均匀抽取
            pool = INST_POOL["mem"]
            lines = [pool[rng.randrange(len(pool))] for _ in range(args.n_inst)]
            args.allow_mem = True
        elif args.mix == "balanced":
            lines = []
            for _ in range(args.n_inst):
                # balanced = int/fp/mem 混合：60% int, 25% fp, 15% mem
                u = rng.random()
                if u < 0.60:
                    p = INST_POOL["int-heavy"]
                elif u < 0.85:
                    p = INST_POOL["fp-heavy"]
                else:
                    p = INST_POOL["mem"]
                    args.allow_mem = True
                lines.append(p[rng.randrange(len(p))])
        else:
            pool = INST_POOL[args.mix]
            lines = [pool[rng.randrange(len(pool))] for _ in range(args.n_inst)]
        seq_name = f"random-{args.mix}-n{args.n_inst}-s{args.seed}"
    else:
        lines, errors = load_sequence(args.seq)
        if errors:
            print("ERROR: sequence sanitization failed:", file=sys.stderr)
            for e in errors:
                print("  " + e, file=sys.stderr)
            return 1
        if not lines:
            sys.exit("ERROR: empty sequence")
        seq_name = os.path.basename(args.seq)

    if args.allow_mem and args.mem_bytes < 64:
        sys.exit("ERROR: --mem-bytes too small")

    elf, c = wrap_and_compile(lines, args.out, seq_name, args.allow_mem,
                              args.mem_bytes, args.iters)
    r = subprocess.run(["file", elf], capture_output=True, text=True)
    print(f"wrapped {len(lines)} lines (iters={args.iters}) -> {elf}")
    print(f"  {r.stdout.strip()}")
    print(f"  wrapper C: {c}")
    return 0


if __name__ == "__main__":
    sys.exit(main())

