/*
 * CHAOSCov — single-run hardware coverage instrumentation for the
 * Harpocrates reproduction (harp plan Task 1.2; metrics per ISCA'24 §II-D).
 *
 * Two coverage families (definitions mirror the paper exactly):
 *   ACE lifetime (bit arrays: IRF, L1D, LSQ): ACE cycles / total ROI cycles
 *     summed over all bits, i.e. AVF. Upper bound of transient-fault
 *     detection capability.
 *   IBR (functional units): effective input bits delivered to the unit /
 *     theoretical max (full-width inputs at every ROI cycle). Correlates
 *     with (does not bound) permanent gate-level fault detection.
 *
 * ROI gating: m5ops workbegin/workend markers (inserted by tools/harp_wrap.py)
 * flip roi_active. Collection hooks short-circuit when !roi_active.
 * The pseudo_inst.cc side calls harp_cov_notify_work_begin/end() (weak
 * default no-op in CHAOSCov.cc; CHAOSCov registers itself there).
 *
 * This skeleton registers stats + detail dump; per-structure collectors
 * arrive in plan Tasks 2.x/3.x/4.1.
 */
#ifndef __CHAOS_COV_CHAOSCOV_HH__
#define __CHAOS_COV_CHAOSCOV_HH__

#include "sim/sim_object.hh"
#include "base/output.hh"
#include "base/types.hh"

#include <cstdint>
#include <string>

namespace gem5
{

class CHAOSCovParams;
namespace o3 { class CPU; }

// Global ROI notification hooks called from sim/pseudo_inst.cc.
// Defined in CHAOSCov.cc; when no CHAOSCov instance exists they are no-ops.
void harp_cov_notify_work_begin();
void harp_cov_notify_work_end();

class CHAOSCov : public SimObject
{
  public:
    CHAOSCov(const CHAOSCovParams &p);
    ~CHAOSCov() override;
    void startup() override;
    void regStats() override;

    // ROI state (also read by collector hooks in later tasks)
    static bool roiActive() { return roi_active; }

    // Notification from the global hooks (pseudo_inst workbegin/workend).
    void onWorkBegin();
    void onWorkEnd();

    // Per-cycle poll from collectors (cycle-granular ROI bookkeeping).
    void tickROICycles() { if (roi_active) roi_cycles++; }

    uint64_t roiCycles() const { return roi_cycles; }

  private:
    o3::CPU *cpu;
    enum class RoiMode { M5Ops, Cycles, All };
    RoiMode roi_mode;
    uint64_t roi_begin_cycle, roi_end_cycle;
    bool write_detail;

    static bool roi_active;         // set/cleared by hooks (or cycle mode)
    static CHAOSCov *instance;      // single active analyzer
    uint64_t roi_cycles = 0;

    OutputStream *detail_stream = nullptr;

  protected:
    struct HarpStats : public statistics::Group
    {
        HarpStats(statistics::Group *parent);
        // --- ROI bookkeeping ---
        statistics::Scalar roiCycles;
        statistics::Scalar roiBeginTick;
        statistics::Scalar roiEndTick;
        // --- structure coverage (placeholders until Tasks 2-4 collectors) ---
        statistics::Scalar irfAvfPlaceholder;
        statistics::Formula irfAvf;
    } harpStats;
};

} // namespace gem5

#endif // __CHAOS_COV_CHAOSCOV_HH__

/*
 * CHAOSCov — Harpocrates coverage analyzer, skeleton (Task 1.2).
 * See CHAOSCov.hh for the metric definitions and ROI contract.
 */
#include "CHAOSCov/CHAOSCov.hh"
#include "params/CHAOSCov.hh"
#include "cpu/o3/cpu.hh"
#include "base/trace.hh"
#include "debug/CHAOSCov.hh"

#include <fstream>
#include <iomanip>

namespace gem5
{

// --- static ROI state shared with collector hooks (Tasks 2-4) ---
bool CHAOSCov::roi_active = false;
CHAOSCov *CHAOSCov::instance = nullptr;

// Global notification hooks (called from sim/pseudo_inst.cc workbegin/end).
// No instance mounted -> no-ops (zero overhead for non-harp runs).
void harp_cov_notify_work_begin() { if (CHAOSCov::instance) CHAOSCov::instance->onWorkBegin(); }
void harp_cov_notify_work_end()   { if (CHAOSCov::instance) CHAOSCov::instance->onWorkEnd(); }

CHAOSCov::CHAOSCov(const CHAOSCovParams &p)
    : SimObject(p),
      cpu(dynamic_cast<o3::CPU *>(p.cpu)),
      roi_begin_cycle(p.roiBeginCycle),
      roi_end_cycle(p.roiEndCycle),
      write_detail(p.writeDetail),
      harpStats(this)
{
    if (!cpu)
        throw std::runtime_error(
            "CHAOSCov: cpu is not an O3CPU — O3-only (IRF/LSQ/IQ hooks)");
    if (p.roiMode == "m5ops")       roi_mode = RoiMode::M5Ops;
    else if (p.roiMode == "cycles") roi_mode = RoiMode::Cycles;
    else                            roi_mode = RoiMode::All;

    if (instance)
        warn("CHAOSCov: multiple instances mounted; the last one wins "
             "(ROI hooks are global)\n");
    instance = this;

    if (roi_mode == RoiMode::All)
        roi_active = true;
}

CHAOSCov::~CHAOSCov()
{
    if (instance == this)
        instance = nullptr;
}

void
CHAOSCov::startup()
{
    if (write_detail) {
        detail_stream = simout.create("harp_cov_detail.log", false, true);
        if (!detail_stream || !detail_stream->stream())
            panic("CHAOSCov: could not open harp_cov_detail.log");
    }
    DPRINTF(CHAOSCov, "CHAOSCov started, roiMode=%d\n", (int)roi_mode);
}

void
CHAOSCov::onWorkBegin()
{
    if (roi_mode != RoiMode::M5Ops)
        return;
    assert(!roi_active);
    roi_active = true;
    DPRINTF(CHAOSCov, "ROI begin @ tick %llu\n", (unsigned long long)curTick());
}

void
CHAOSCov::onWorkEnd()
{
    if (roi_mode != RoiMode::M5Ops)
        return;
    // Marker pair seen; close the window. (Re-open supported: harp_wrap
    // emits exactly one pair, but keep it robust for multi-ROI workloads.)
    roi_active = false;
    DPRINTF(CHAOSCov, "ROI end @ tick %llu (roi_cycles=%llu)\n",
            (unsigned long long)curTick(), (unsigned long long)roi_cycles);
    if (detail_stream && detail_stream->stream())
        *(detail_stream->stream())
            << "# workend @ tick " << curTick()
            << " roi_cycles " << roi_cycles << "\n";
}

void
CHAOSCov::regStats()
{
    SimObject::regStats();
}

CHAOSCov::HarpStats::HarpStats(statistics::Group *parent)
    : statistics::Group(parent, "harp"),
      ADD_STAT(roiCycles, statistics::units::Cycle::get(),
               "Cycles inside the ROI window"),
      ADD_STAT(roiBeginTick, statistics::units::Tick::get(),
               "Tick of the first workbegin marker (m5ops ROI mode)"),
      ADD_STAT(roiEndTick, statistics::units::Tick::get(),
               "Tick of the workend marker (m5ops ROI mode)")
{
}

} // namespace gem5

