124	void
125	CHAOSCov::irfOnWrite(int class_type, int idx)
126	{
127	    if (!roi_active) return;
128	    auto &st = irf_state[class_type][idx];
129	    const uint64_t now = roi_cycles;
130	    // Close the previous value's interval: if it was read at least once,
131	    // its ACE contribution [birth, last_read] has already been accumulated
132	    // incrementally at each read (see irfOnRead); if never read, it
133	    // contributes nothing (write→write overwrite = un-ACE).
134	    // Start the new value's interval.
135	    st.birth = now;
136	    st.last_read = now;
137	    st.has_value = true;
138	    st.ever_read = false;
139	}
140	
141	void
142	CHAOSCov::irfOnRead(int class_type, int idx)
143	{
144	    if (!roi_active) return;
145	    auto &st = irf_state[class_type][idx];
146	    if (!st.has_value) return;    // read of a slot with no ROI value (e.g.
147	                                  // value written before ROI): treat the
148	                                  // readable residency as ACE from ROI start
149	    if (!st.ever_read) {
150	        // First read: accumulate [birth, now] (write→read interval).
151	        irf_ace_cycles[class_type] += now - st.birth;
152	        st.ever_read = true;
153	    } else {
154	        // read→read: extend to now.
155	        irf_ace_cycles[class_type] += now - st.last_read;
156	    }
157	    st.last_read = now;
158	}
