160	void
161	CHAOSCov::irfOnAlloc(int class_type, int idx)
162	{
163	    // Allocation itself is un-ACE (free-list residency). Nothing to do:
164	    // the interval only starts at write. Reset stale state defensively.
165	    auto &st = irf_state[class_type][idx];
166	    st.has_value = false;
167	    st.ever_read = false;
168	}
