171	CHAOSCov::irfOnFree(int class_type, int idx)
172	{
173	    // Freeing closes any open interval; unread tail (last_read..free) is
174	    // un-ACE and was never accumulated. has_value=false stops future reads.
175	    auto &st = irf_state[class_type][idx];
176	    st.has_value = false;
177	}
