181	{
182	    // ROI end: values still open with reads (read→ROI-end tail is un-ACE —
183	    // the paper's analysis stops at the last confirmed use). Nothing to
184	    // add; just count how many intervals were live for the detail dump.
185	    for (int c = 0; c < 2; c++) {
