/** Get the next available register from the free list */
PhysRegIdPtr getReg()
{
    assert(!freeRegs.empty());
    PhysRegIdPtr free_reg = freeRegs.front();
    freeRegs.pop();
    // Harpocrates IRF-ACE: allocation event (free-list residency is
    // un-ACE; resets any stale interval state for the slot).
    if (harp_enabled)
        harp_cov_on_prf_alloc(free_reg->classValue() == IntRegClass
                                  ? 0 : 1,
                              free_reg->index());
    return free_reg;
}

/** Add a physical register to the free list */
void addReg(PhysRegIdPtr reg)
{
    // Harpocrates IRF-ACE: free event (closes the slot's open interval;
    // the post-last-read idle tail is un-ACE and never accumulated).
    if (harp_enabled)
        harp_cov_on_prf_free(reg->classValue() == IntRegClass ? 0 : 1,
                             reg->index());
    freeRegs.push(reg);
}

