/*
 * CHAOSGateFU — synthetic gate-level netlist FU fault injector (Task 5.3).
 * Implementation: netlist synthesis (Kogge-Stone adder / shift-add
 * multiplier), structural stuck-at evaluation, and the writeback oracle.
 */
#include "CHAOSGateFU/CHAOSGateFU.hh"
#include "params/CHAOSGateFU.hh"
#include "cpu/o3/cpu.hh"
#include "enums/OpClass.hh"
#include "base/trace.hh"

#include <iostream>

namespace gem5
{

CHAOSGateFU *CHAOSGateFU::instance = nullptr;
bool gatefu_enabled = false;

// ---------------------------------------------------------------------------
// Netlist synthesis
// ---------------------------------------------------------------------------
// Helper adders on the flat gate list. PI encoding (pi_width = 2*w):
//   PI[i]        = a[i]   (i < w)
//   PI[w + j]    = b[j]
// Returns the gate index producing the sum/output bit.

int
CHAOSGateFU::synthGate(GateType t, int in0, int in1)
{
    gates.push_back({t, in0, in1});
    return (int)gates.size() - 1;
}

// Kogge-Stone prefix adder: standard sparse structure.
//   p[i] = a XOR b, g[i] = a AND b  (preprocess)
//   prefix: (g,p) o (G,P) = (g OR (p AND G), p AND P)
//   sum[i] = p[i] XOR carry[i-1]; carry[i] = g-prefix[i]
void
CHAOSGateFU::synthesizeAdder(int width)
{
    gates.clear();
    po_gates.clear();
    pi_width = 2 * width;
    // bit slices of intermediates, indexed [level][bit]
    std::vector<std::vector<int>> p(width), g(width);

    // Preprocess.
    for (int i = 0; i < width; i++) {
        int ai = -(i + 1);              // PI a[i]
        int bi = -(width + i + 1);      // PI b[i]
        p[i].push_back(synthGate(XOR, ai, bi));
        g[i].push_back(synthGate(AND, ai, bi));
    }
    // Prefix network (Kogge-Stone: distances 1,2,4,...).
    int level = 0;
    for (int d = 1; d < width; d <<= 1) {
        std::vector<int> np(width), ng(width);
        for (int i = 0; i < width; i++) {
            int pv = p[i].back(), gv = g[i].back();
            if (i - d >= 0) {
                int pg = p[i - d].back(), gg = g[i - d].back();
                int pand = synthGate(AND, pv, gg);      // p & G
                int gor  = synthGate(OR, gv, pand);      // g | (p & G)
                int pandp = synthGate(AND, pv, pg);      // p & P
                np[i] = pandp;
                ng[i] = gor;
            } else {
                np[i] = pv;
                ng[i] = gv;
            }
        }
        for (int i = 0; i < width; i++) {
            p[i].push_back(np[i]);
            g[i].push_back(ng[i]);
        }
        level++;
    }
    // Sum: sum[i] = p[i] XOR c[i-1], c[i-1] = g[i-1] (final prefix),
    // sum[0] = p[0]. Carry-out = g[width-1] (bit `width` of the PO).
    for (int i = 0; i < width; i++) {
        if (i == 0) {
            po_gates.push_back(p[0].back());
        } else {
            po_gates.push_back(synthGate(XOR, p[i].back(), g[i - 1].back()));
        }
    }
    // Carry-out as an extra PO (bit `width`); width+1 outputs total.
    po_gates.push_back(g[width - 1].back());
}

// Shift-add array multiplier: acc = 0; for i in 0..w-1: if b[i], add
// (a << i) to acc using a fresh full-width adder built from the same
// gate primitives (PIs of each sub-adder are existing nets, not PIs —
// the netlist is one flat combinational structure).
// For injectability we need the partial products as gates: pp[i][j] =
// a[j] AND b[i]; then the accumulation adders take gate outputs as inputs.
void
CHAOSGateFU::synthesizeMultiplier(int width)
{
    gates.clear();
    po_gates.clear();
    pi_width = 2 * width;
    // NOT on b[i] not needed; build AND partial products.
    // pp[i][j] = a[j] & b[i]
    std::vector<std::vector<int>> pp(width, std::vector<int>(width));
    for (int i = 0; i < width; i++) {
        int bi = -(width + i + 1);
        for (int j = 0; j < width; j++) {
            int aj = -(j + 1);
            pp[i][j] = synthGate(AND, aj, bi);
        }
    }
    // Accumulate: acc (2w bits, as gate indices; -1 means constant 0 —
    // represented by a constant gate we synthesize once: const0 = AND(a0, NOT a0)).
    // Simpler: start with row0 partial product as the initial accumulator
    // (shifted by 0) and no explicit zero constant.
    std::vector<int> acc(2 * width, -1);
    for (int j = 0; j < width; j++)
        acc[j] = pp[0][j];
    for (int i = 1; i < width; i++) {
        // addend = pp[i][*] << i : bits [i, i+width)
        // adder over 2w bits, carry chain of plain full adders
        // (ripple — gate count larger but structure simple & injectable).
        std::vector<int> sum(2 * width, -1);
        int carry = -1;
        for (int k = 0; k < 2 * width; k++) {
            int x = acc[k];
            // y bit: partial-product row i contributes at position i+j
            int j = k - i;
            int y = (0 <= j && j < width) ? pp[i][j] : -1;
            if (x < 0 && y < 0 && carry < 0) {
                sum[k] = -1;
                carry = -1;
                continue;
            }
            // half/full adder from primitives
            int s, c_out;
            if (x < 0 && y < 0) {           // only carry
                sum[k] = carry;
                c_out = -1;
            } else if (x < 0 || y < 0) {    // one operand + carry
                int v = (x >= 0) ? x : y;
                s = synthGate(XOR, v, carry);
                int vand = synthGate(AND, v, carry);
                c_out = vand;
                sum[k] = s;
            } else {                         // x + y + carry
                int xyc = synthGate(XOR, x, y);
                s = synthGate(XOR, xyc, carry >= 0 ? carry : x /*unused*/);
                if (carry < 0) {
                    s = xyc;                 // no carry-in
                    int xy = synthGate(AND, x, y);
                    c_out = xy;
                } else {
                    int xy = synthGate(AND, x, y);
                    int c1 = synthGate(OR, xy, synthGate(AND, xyc, carry));
                    // s already includes carry via XOR above
                    c_out = c1;
                }
                sum[k] = s;
            }
            carry = c_out;
        }
        acc = sum;
    }
    // POs: the low 2w bits of acc (high bits beyond 2w-1 dropped — the
    // carry out of the top would be bit 2w; 64x64 -> 128 bits exactly).
    for (int k = 0; k < 2 * width; k++)
        po_gates.push_back(acc[k]);
}

// ---------------------------------------------------------------------------
// Evaluation
// ---------------------------------------------------------------------------
std::vector<bool>
CHAOSGateFU::evalNet(const std::vector<bool> &pis, int stuck_gate,
                     int stuck_val) const
{
    std::vector<bool> val(gates.size());
    auto read = [&](int in) -> bool {
        if (in < 0)
            return pis[-in - 1];
        return val[in];
    };
    for (size_t gi = 0; gi < gates.size(); gi++) {
        const Gate &g = gates[gi];
        bool v;
        switch (g.type) {
          case AND: v = read(g.in0) && read(g.in1); break;
          case OR:  v = read(g.in0) || read(g.in1); break;
          case XOR: v = read(g.in0) != read(g.in1); break;
          case NOT: v = !read(g.in0); break;
          default:  v = false;
        }
        // Structural stuck-at: force AFTER computing, before fanouts read.
        if ((int)gi == stuck_gate)
            v = (stuck_val != 0);
        val[gi] = v;
    }
    std::vector<bool> po(po_gates.size());
    for (size_t i = 0; i < po_gates.size(); i++)
        po[i] = po_gates[i] >= 0 ? val[po_gates[i]] : false;
    return po;
}

bool
CHAOSGateFU::evaluate(int op_class, uint64_t a, uint64_t b, uint64_t &result)
{
    if (op_class != target_opclass)
        return false;
    if (cpu->curCycle() < Cycles(first_clock))
        return false;
    eval_count++;
    stats.numEvals++;

    std::vector<bool> pis(pi_width, false);
    for (int i = 0; i < 64; i++) {
        pis[i] = (a >> i) & 1;
        if (pi_width > (size_t)(64 + i))
            pis[64 + i] = (b >> i) & 1;
    }
    std::vector<bool> po = evalNet(pis, stuck_gate, stuck_val);
    // PO width: adder -> 65 (64 sum + carry), multiplier -> 128.
    uint64_t r = 0;
    for (size_t i = 0; i < po.size() && i < 64; i++)
        if (po[i])
            r |= (1ULL << i);
    result = r;
    // Track divergence vs the architectural op (the caller's a?b semantics:
    // adder -> a+b, multiplier -> a*b — computed here for the diff stat).
    uint64_t arch = (target_opclass == 0 /*IntAlu*/) ? (uint64_t)(a + b)
                                                     : (uint64_t)(a * b);
    if (r != arch) {
        diff_count++;
        stats.numDiffs++;
    }
    return true;
}

// Oracle used by cpu/o3/dyn_inst.hh setRegOperand.
bool
gatefu_evaluate(int op_class, uint64_t a, uint64_t b, uint64_t &result)
{
    if (!CHAOSGateFU::instance)
        return false;
    return CHAOSGateFU::instance->evaluate(op_class, a, b, result);
}

// ---------------------------------------------------------------------------
// SimObject plumbing
// ---------------------------------------------------------------------------
CHAOSGateFU::CHAOSGateFU(const CHAOSGateFUParams &p)
    : SimObject(p),
      cpu(dynamic_cast<o3::CPU *>(p.cpu)),
      write_log(p.writeLog),
      stats(this)
{
    if (!cpu)
        throw std::runtime_error("CHAOSGateFU: cpu is not an O3CPU");

    const std::string &n = p.targetOpClass;
    target_opclass = -1;
    for (int i = 0; i < enums::Num_OpClass; i++) {
        if (enums::OpClassStrings[i] == n) {
            target_opclass = i;
            break;
        }
    }
    if (target_opclass < 0)
        throw std::runtime_error(
            "CHAOSGateFU: unknown targetOpClass '" + n + "'");

    stuck_gate = p.targetGate;
    stuck_val = p.stuckPolarity;
    first_clock = p.firstClock;

    // Synthesize the netlist for this FU class.
    if (n == "IntAlu")
        synthesizeAdder(64);
    else if (n == "IntMult")
        synthesizeMultiplier(64);
    else
        throw std::runtime_error(
            "CHAOSGateFU: netlist available for IntAlu | IntMult (got '"
            + n + "'; FP netlists are Task 5.4)");

    if (instance)
        warn("CHAOSGateFU: multiple instances; last one wins\n");
    instance = this;
    gatefu_enabled = true;

    if (write_log) {
        log_stream = simout.create("gatefu_injections.log", false, true);
        if (!log_stream || !log_stream->stream())
            panic("CHAOSGateFU: could not open gatefu_injections.log");
    }
    stats.numGates = gates.size();
}

CHAOSGateFU::~CHAOSGateFU()
{
    if (instance == this) {
        instance = nullptr;
        gatefu_enabled = false;
    }
}

// Helper used by the .cc above (declared in the class, defined here).
int
CHAOSGateFU::synthGate(GateType t, int in0, int in1)
{
    gates.push_back({t, in0, in1});
    return (int)gates.size() - 1;
}

CHAOSGateFU::Stats::Stats(statistics::Group *parent)
    : statistics::Group(parent),
      ADD_STAT(numEvals, statistics::units::Count::get(),
               "Netlist evaluations (ops of the target class)"),
      ADD_STAT(numDiffs, statistics::units::Count::get(),
               "Netlist result differs from architectural value (fault "
               "manifestations)"),
      ADD_STAT(numGates, statistics::units::Count::get(),
               "Synthesized gate count of the FU netlist")
{
}

} // namespace gem5

