            int xc = synthGate(AND, xyc, carry);  // (x^y) & c
            carry = synthGate(OR, xy, xc);        // majority
        }
        acc = sum;
    }
    for (int k = 0; k < 2 * width; k++)
        po_gates.push_back(acc[k]);
}

